    tuningOwnership: "advisory",
    event: "PreToolUse",
    matcher: "mcp__minsky__tasks_create",
    module: () => import("./duplicate-signature-scan").then((m) => ({ run: m.run })),
    // MUST stay above the module's SCAN_TIMEOUT_MS (15s), so the guard's OWN
