    tuningOwnership: "advisory",
    event: "PreToolUse",
    matcher: "mcp__minsky__tasks_create",
    module: () => import("./duplicate-check-search-provenance").then((m) => ({ run: m.run })),
    // A regex over one paragraph plus a membership test over lines the
